arguments.content:
:root {
  --primary: #003B95;
  --accent: #006CE4;
  --highlight: #FFB700;
  --highlight-hover: #e6a500;
  --bg-color: #ffffff;
  --bg-alt: #f5f5f5;
  --bg-light-blue: #f0f6ff;
  --text-dark: #1a1a1a;
  --text-muted: #595959;
  --border: #e6e6e6;
  --border-radius: 8px;
  --border-radius-lg: 16px;
  --shadow: 0 4px 12px rgba(0, 0, 0, 0.05);
  --shadow-hover: 0 8px 24px rgba(0, 0, 0, 0.12);
  --transition: all 0.2s ease-in-out;
  --container-max: 1200px;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  color: var(--text-dark);
  background-color: var(--bg-color);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { text-decoration: none; color: inherit; }
ul { list-style: none; }
img { max-width: 100%; display: block; border-radius: var(--border-radius); }

.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 20px;
}

/* Typography */
h1 { font-size: 3rem; font-weight: 700; line-height: 1.2; letter-spacing: -0.02em; margin-bottom: 0.5rem; }
h2 { font-size: 2rem; font-weight: 700; line-height: 1.3; margin-bottom: 0.5rem; }
h3 { font-size: 1.25rem; font-weight: 600; line-height: 1.4; margin-bottom: 0.25rem; }
.subtitle { font-size: 1.25rem; color: var(--text-muted); margin-bottom: 2rem; }

/* Header & Nav */
header { background-color: var(--primary); color: white; padding-bottom: 1rem; }
.top-nav { display: flex; justify-content: space-between; align-items: center; padding: 1.5rem 0; }
.logo { font-size: 1.5rem; font-weight: 700; }
.nav-actions { display: flex; gap: 1rem; align-items: center; }
.btn-nav { background: transparent; color: white; border: none; font-weight: 600; padding: 0.5rem 1rem; cursor: pointer; border-radius: 4px; }
.btn-nav:hover { background: rgba(255,255,255,0.1); }
.btn-nav-outline { border: 1px solid white; border-radius: var(--border-radius); }
.btn-nav-outline:hover { background: white; color: var(--primary); }
.main-nav { display: flex; gap: 0.5rem; overflow-x: auto; scrollbar-width: none; }
.main-nav::-webkit-scrollbar { display: none; }
.main-nav a { padding: 0.75rem 1.25rem; border-radius: 2rem; font-weight: 500; white-space: nowrap; transition: var(--transition); display: flex; align-items: center; gap: 0.5rem; color: rgba(255,255,255,0.8); }
.main-nav a:hover { background: rgba(255,255,255,0.1); color: white; }
.main-nav a.active { border: 1px solid white; background: rgba(255,255,255,0.1); color: white; }

/* Buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem;
  padding: 0.75rem 1.5rem; border-radius: var(--border-radius); font-weight: 600; cursor: pointer; transition: var(--transition); border: none; font-size: 1rem;
}
.btn-primary { background-color: var(--accent); color: white; }
.btn-primary:hover { background-color: #0056b3; }
.btn-accent { background-color: var(--highlight); color: var(--text-dark); }
.btn-accent:hover { background-color: var(--highlight-hover); }
.btn-outline { background: transparent; color: var(--accent); border: 1px solid var(--accent); }
.btn-outline:hover { background: var(--bg-light-blue); }
.btn-large { padding: 1rem 2rem; font-size: 1.125rem; }

/* Search Box */
.search-wrapper { position: relative; margin-top: -3rem; z-index: 10; margin-bottom: 3rem; }
.search-box {
  background: white; padding: 1rem; border-radius: var(--border-radius); box-shadow: 0 4px 16px rgba(0,0,0,0.1);
  display: flex; gap: 0.5rem; flex-wrap: wrap; border: 4px solid var(--highlight);
}
.search-input {
  flex: 1 1 200px; display: flex; align-items: center; background: white; border: 1px solid var(--border);
  border-radius: 4px; padding: 0.5rem; position: relative;
}
.search-input i { color: var(--text-muted); margin: 0 0.5rem; }
.search-input input { border: none; outline: none; width: 100%; font-size: 1rem; padding: 0.5rem 0; color: var(--text-dark); }
.search-input input::placeholder { color: var(--text-muted); }
.search-box .btn { flex: 0 0 auto; }
.search-options { margin-top: 1rem; display: flex; gap: 1rem; align-items: center; color: var(--text-dark); }
.search-options label { display: flex; align-items: center; gap: 0.5rem; cursor: pointer; }

/* Sections */
section { padding: 4rem 0; }
section.bg-alt { background-color: var(--bg-alt); }
.section-header { margin-bottom: 2rem; }

/* Trust Badges */
.trust-badges { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 2rem; padding: 2rem 0; }
.trust-badge { display: flex; align-items: flex-start; gap: 1rem; }
.trust-badge-icon { background: var(--bg-light-blue); color: var(--accent); width: 48px; height: 48px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 1.5rem; flex-shrink: 0; }
.trust-badge h4 { font-weight: 600; margin-bottom: 0.25rem; }
.trust-badge p { color: var(--text-muted); font-size: 0.875rem; }

/* Cards & Grids */
.grid { display: grid; gap: 1.5rem; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
.grid-5 { grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); }

.card {
  background: white; border-radius: var(--border-radius); overflow: hidden;
  box-shadow: var(--shadow); transition: var(--transition); border: 1px solid var(--border); display: flex; flex-direction: column; cursor: pointer;
}
.card:hover { box-shadow: var(--shadow-hover); transform: translateY(-4px); }
.card-img { height: 200px; background-color: #ddd; background-size: cover; background-position: center; border-radius: var(--border-radius) var(--border-radius) 0 0; }
.card-content { padding: 1rem; display: flex; flex-direction: column; flex-grow: 1; }
.card-title { font-weight: 600; font-size: 1.125rem; margin-bottom: 0.25rem; }
.card-subtitle { color: var(--text-muted); font-size: 0.875rem; margin-bottom: 0.5rem; }
.card-rating { display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem; font-size: 0.875rem; font-weight: 600;}
.badge { background: var(--primary); color: white; padding: 0.25rem 0.5rem; border-radius: 4px; border-top-right-radius: 0; }
.card-price { margin-top: auto; font-size: 1.25rem; font-weight: 700; text-align: right; }
.card-price-old { text-decoration: line-through; color: var(--text-muted); font-size: 0.875rem; margin-right: 0.5rem; font-weight: normal; }

.destination-card { position: relative; overflow: hidden; border-radius: var(--border-radius); border: none; box-shadow: none; }
.destination-card .card-img { height: 240px; border-radius: var(--border-radius); transition: transform 0.5s; }
.destination-card:hover .card-img { transform: scale(1.05); }
.destination-overlay { position: absolute; inset: 0; background: linear-gradient(to top, rgba(0,0,0,0.8) 0%, transparent 60%); display: flex; flex-direction: column; justify-content: flex-end; padding: 1.5rem; color: white; border-radius: var(--border-radius); }
.destination-overlay h3 { margin: 0; font-size: 1.5rem; text-shadow: 0 2px 4px rgba(0,0,0,0.5); }
.destination-overlay p { margin: 0; font-weight: 500; text-shadow: 0 1px 2px rgba(0,0,0,0.5); }

/* Offers */
.offer-card { background: white; border-radius: var(--border-radius); border: 1px solid var(--border); box-shadow: var(--shadow); display: flex; overflow: hidden; }
.offer-content { padding: 2rem; flex: 1; display: flex; flex-direction: column; justify-content: center; align-items: flex-start; }
.offer-img { width: 300px; background-color: var(--highlight); background-image: linear-gradient(135deg, var(--highlight) 0%, #ff8c00 100%); }
.offer-img.img-credit { background: var(--primary); background-image: linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%); }
.offer-card h3 { margin-bottom: 1rem; }
.offer-card p { color: var(--text-muted); margin-bottom: 1.5rem; }

/* Tabs */
.tabs-nav { display: flex; gap: 0.5rem; margin-bottom: 2rem; border-bottom: 1px solid var(--border); overflow-x: auto; padding-bottom: 0.5rem; }
.tab-btn { background: transparent; border: none; padding: 0.75rem 1.25rem; font-size: 1rem; font-weight: 500; color: var(--text-muted); cursor: pointer; border-radius: 2rem; transition: var(--transition); display: flex; align-items: center; gap: 0.5rem; white-space: nowrap; }
.tab-btn:hover { background: var(--bg-alt); color: var(--text-dark); }
.tab-btn.active { background: var(--bg-light-blue); color: var(--accent); border: 1px solid var(--accent); }
.tab-content { display: none; animation: fadeIn 0.3s ease-in-out; }
.tab-content.active { display: block; }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }

/* Carousel (Unique Properties) */
.carousel-wrapper { position: relative; }
.carousel { display: flex; gap: 1.5rem; overflow-x: auto; scroll-behavior: smooth; scrollbar-width: none; padding-bottom: 1rem; margin-left: -5px; padding-left: 5px; }
.carousel::-webkit-scrollbar { display: none; }
.carousel .card { flex: 0 0 280px; }
.carousel-btn { position: absolute; top: 50%; transform: translateY(-50%); width: 40px; height: 40px; border-radius: 50%; background: white; border: 1px solid var(--border); box-shadow: var(--shadow); display: flex; align-items: center; justify-content: center; cursor: pointer; z-index: 2; font-size: 1.25rem; color: var(--text-dark); }
.carousel-btn:hover { background: var(--bg-alt); }
.carousel-btn.prev { left: -20px; }
.carousel-btn.next { right: -20px; }

/* Accordion (FAQ) */
.accordion { border: 1px solid var(--border); border-radius: var(--border-radius); overflow: hidden; }
.accordion-item { border-bottom: 1px solid var(--border); }
.accordion-item:last-child { border-bottom: none; }
.accordion-header { padding: 1.5rem; background: white; cursor: pointer; display: flex; justify-content: space-between; align-items: center; font-weight: 600; font-size: 1.125rem; transition: var(--transition); }
.accordion-header:hover { background: var(--bg-alt); }
.accordion-icon { transition: transform 0.3s; }
.accordion-item.active .accordion-icon { transform: rotate(180deg); }
.accordion-content { padding: 0 1.5rem; max-height: 0; overflow: hidden; transition: max-height 0.3s ease-out; background: white; color: var(--text-muted); }
.accordion-item.active .accordion-content { padding-bottom: 1.5rem; }

/* CTA Banner */
.cta-banner { background: var(--primary); border-radius: var(--border-radius); padding: 3rem; color: white; display: flex; justify-content: space-between; align-items: center; margin: 4rem 0; box-shadow: 0 8px 32px rgba(0,59,149,0.2); }
.cta-banner h2 { margin-bottom: 0.5rem; }
.cta-banner p { color: rgba(255,255,255,0.8); margin-bottom: 0; font-size: 1.125rem; }
.cta-actions { display: flex; gap: 1rem; }

/* Footer */
footer { background: white; padding: 4rem 0 2rem; border-top: 1px solid var(--border); font-size: 0.875rem; }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 2rem; margin-bottom: 3rem; }
.footer-col h4 { font-size: 1rem; margin-bottom: 1rem; font-weight: 600; }
.footer-col ul li { margin-bottom: 0.5rem; }
.footer-col a { color: var(--accent); transition: var(--transition); }
.footer-col a:hover { color: #0056b3; text-decoration: underline; }
.footer-bottom { text-align: center; color: var(--text-muted); padding-top: 2rem; border-top: 1px solid var(--border); }

/* Responsive */
@media (max-width: 992px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .offer-card { flex-direction: column; }
  .offer-img { width: 100%; height: 200px; }
  .search-box { flex-direction: column; }
  .cta-banner { flex-direction: column; text-align: center; gap: 2rem; }
}
@media (max-width: 768px) {
  h1 { font-size: 2.25rem; }
  .grid-2 { grid-template-columns: 1fr; }
  .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .carousel-btn { display: none; }
  .top-nav { flex-direction: column; gap: 1rem; }
}

/* Helpers */
.text-accent { color: var(--accent); }
.d-flex { display: flex; }
.align-center { align-items: center; }
.gap-2 { gap: 0.5rem; }
.mt-4 { margin-top: 1rem; }
.mb-4 { margin-bottom: 1rem; }

document.addEventListener('DOMContentLoaded', () => {
  // Tabs logic
  const tabGroups = document.querySelectorAll('.tabs-nav');
  tabGroups.forEach(group => {
    const tabs = group.querySelectorAll('.tab-btn');
    tabs.forEach(tab => {
      tab.addEventListener('click', (e) => {
        // Prevent default if it's an anchor (though they are buttons)
        e.preventDefault();

        // Remove active class from all tabs in this group
        tabs.forEach(t => t.classList.remove('active'));
        // Add active class to clicked tab
        tab.classList.add('active');

        // Find corresponding content
        const targetId = tab.getAttribute('data-tab-target');
        const container = group.parentElement; // Assuming container wraps nav and contents
        const contents = container.querySelectorAll('.tab-content');

        contents.forEach(content => {
          content.classList.remove('active');
          if (content.id === targetId) {
            content.classList.add('active');
          }
        });
      });
    });
  });

  // Carousel logic
  const carousels = document.querySelectorAll('.carousel-wrapper');
  carousels.forEach(wrapper => {
    const carousel = wrapper.querySelector('.carousel');
    const prevBtn = wrapper.querySelector('.carousel-btn.prev');
    const nextBtn = wrapper.querySelector('.carousel-btn.next');

    if (carousel && prevBtn && nextBtn) {
      prevBtn.addEventListener('click', () => {
        carousel.scrollBy({ left: -300, behavior: 'smooth' });
      });
      nextBtn.addEventListener('click', () => {
        carousel.scrollBy({ left: 300, behavior: 'smooth' });
      });
    }
  });

  // Accordion logic
  const accordions = document.querySelectorAll('.accordion');
  accordions.forEach(accordion => {
    const items = accordion.querySelectorAll('.accordion-item');
    items.forEach(item => {
      const header = item.querySelector('.accordion-header');
      header.addEventListener('click', () => {
        const isActive = item.classList.contains('active');

        // Close all items
        items.forEach(i => {
          i.classList.remove('active');
          i.querySelector('.accordion-content').style.maxHeight = null;
        });

        // If not active, open it
        if (!isActive) {
          item.classList.add('active');
          const content = item.querySelector('.accordion-content');
          content.style.maxHeight = content.scrollHeight + "px";
        }
      });
    });
  });

  // Prevent form submission for search buttons
  const searchButtons = document.querySelectorAll('.search-box .btn');
  searchButtons.forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      // Mock search action
      const btnText = btn.textContent;
      btn.textContent = 'Searching...';
      setTimeout(() => {
        btn.textContent = btnText;
      }, 800);
    });
  });

  // Radio button interactions for Packages
  const packageRadios = document.querySelectorAll('input[name="package-type"]');
  if (packageRadios.length > 0) {
    packageRadios.forEach(radio => {
      radio.addEventListener('change', (e) => {
        // Just for visual effect in mockup
        console.log('Selected package:', e.target.value);
      });
    });
  }
});
